import asyncio
from typing import TypeAlias

import aiohttp

Result: TypeAlias = dict[str, str | int | None]


async def fetch_all(
    urls: list[str],
    timeout: float = 5.0,
    retries: int = 2,
) -> list[Result]:
    """Fetch URLs concurrently, preserving input order.

    Each attempt has its own timeout. Network errors, timeouts, and HTTP
    5xx responses receive up to `retries` additional attempts, separated
    by exponential backoff starting at 0.5 seconds. HTTP 4xx responses
    are returned normally. Failed fetches have null status and body.
    Errors, including cancellation, are returned rather than raised.
    """

    def failure(url: str, exc: BaseException) -> Result:
        return {
            "url": url,
            "status": None,
            "body": None,
            "error": f"{type(exc).__name__}: {exc}",
        }

    async def fetch_one(session: aiohttp.ClientSession, url: str) -> Result:
        try:
            for attempt in range(retries + 1):
                try:
                    async with session.get(
                        url, timeout=aiohttp.ClientTimeout(total=timeout)
                    ) as response:
                        if 500 <= response.status < 600:
                            # Exit the response context before backing off.
                            error: Exception = RuntimeError(
                                f"HTTP {response.status}: {response.reason}"
                            )
                        else:
                            body: str = await response.text()
                            return {
                                "url": url,
                                "status": response.status,
                                "body": body,
                                "error": None,
                            }
                except (aiohttp.ClientConnectionError,
                        aiohttp.ClientPayloadError,
                        asyncio.TimeoutError) as exc:
                    error = exc

                if attempt == retries:
                    return failure(url, error)

                await asyncio.sleep(0.5 * (2 ** attempt))

        except (Exception, asyncio.CancelledError) as exc:
            return failure(url, exc)

        return failure(url, RuntimeError("No request attempts were made"))

    try:
        if timeout <= 0:
            raise ValueError("timeout must be positive")
        if retries < 0:
            raise ValueError("retries must be nonnegative")

        # Remove the connector's default concurrency limit.
        async with aiohttp.ClientSession(
            connector=aiohttp.TCPConnector(limit=0)
        ) as session:
            return list(
                await asyncio.gather(*(fetch_one(session, url) for url in urls))
            )
    except (Exception, asyncio.CancelledError) as exc:
        return [failure(url, exc) for url in urls]


async def main() -> None:
    results: list[Result] = await fetch_all(
        [
            "https://example.com",
            "https://www.python.org",
            "https://httpbin.org/status/503",
        ]
    )
    for result in results:
        print(result)


if __name__ == "__main__":
    asyncio.run(main())
