function castRay(s, camera, cameraX) {
  const rayX = camera.dirX + camera.planeX * cameraX;
  const rayY = camera.dirY + camera.planeY * cameraX;
  let cellX = Math.floor(s.player.x);
  let cellY = Math.floor(s.player.y);
