    ? (s.player.x - cellX) * deltaX
    : (cellX + 1 - s.player.x) * deltaX;
  let sideY = rayY < 0
    ? (s.player.y - cellY) * deltaY
    : (cellY + 1 - s.player.y) * deltaY;

