  const cosCorrection = (rayX * camera.dirX + rayY * camera.dirY) / rayLength;

  for (;;) {
    let side, parameter;
    // DDA: advance to the next exact grid boundary.
    if (sideX < sideY) {
      parameter = sideX;
      sideX += deltaX;
      cellX += stepX;
      side = 0;
    } else {
      parameter = sideY;
      sideY += deltaY;
      cellY += stepY;
      side = 1;
    }

    const tile = s.map[cellY]?.[cellX];
    if (tile === 0 || tile === 6) continue;

    // Euclidean ray length times cos(ray angle - view angle).
    // With camera-plane rays this equals the DDA parameter.
    const distance = Math.max(0.0001, parameter * rayLength * cosCorrection);
    const coordinate = side === 0
      ? s.player.y + parameter * rayY
      : s.player.x + parameter * rayX;
    let u = coordinate - Math.floor(coordinate);
    if ((side === 0 && rayX > 0) || (side === 1 && rayY < 0)) u = 1 - u;

    const door = tile === 4 ? s.doors.get(`${cellX},${cellY}`) : null;
    const hit = {
      distance, u, side,
      texture: door?.secret ? 1 : (tile || 1),
      lower: 0,
      upper: 1
    };
    if (door?.open) {
      // An open arch has a curved lintel, with empty space underneath.
      hit.lower = 0.72 + 0.16 * Math.sqrt(Math.max(0, 1 - (u * 2 - 1) ** 2));
      arches.push(hit);
      continue; // Continue DDA through the opening to the wall beyond it.
    }
    return { wall: hit, arches };
  }
}

function drawWallColumn(s, x, hit, isArch = false) {
  const projectedHeight = PROJECTION / hit.distance;
  const fullTop = HEIGHT / 2 - projectedHeight / 2;
  const top = Math.max(0, Math.ceil(fullTop + (1 - hit.upper) * projectedHeight));
