    x, top, 1, bottom - top
  );

  const distanceShade = Math.min(1, Math.max(0.16, 2.8 / hit.distance));
  const shade = distanceShade * (hit.side === 1 ? 0.78 : 1);
  ctx.fillStyle = `rgba(0,0,0,${1 - shade})`;
  ctx.fillRect(x, top, 1, bottom - top);

  if (isArch) {
    s.archOccluders[x].push({ top, bottom, distance: hit.distance });
  }
}

function drawSpriteColumn(s, x, depth, top, bottom, sourceX) {
  if (depth >= s.zBuffer[x]) return;
  let visible = [[Math.max(0, top), Math.min(HEIGHT, bottom)]];
  // Arches only occlude their lintel pixels, not the opening underneath.
  for (const occluder of s.archOccluders[x]) {
    if (depth <= occluder.distance) continue;
    const next = [];
    for (const [a, b] of visible) {
      if (occluder.bottom <= a || occluder.top >= b) {
        next.push([a, b]);
      } else {
        if (a < occluder.top) next.push([a, occluder.top]);
        if (b > occluder.bottom) next.push([occluder.bottom, b]);
      }
    }
    visible = next;
  }
  for (const [a, b] of visible) {
    if (b <= a) continue;
    ctx.drawImage(
      exitSprite,
      sourceX, (a - top) / (bottom - top) * 64,
      1, (b - a) / (bottom - top) * 64,
      x, a, 1, b - a
    );
  }
}

function drawExitBeacon(s, camera) {
  const dx = s.exit.x - s.player.x;
  const dy = s.exit.y - s.player.y;
  const depth = dx * camera.dirX + dy * camera.dirY;
  if (depth <= 0.08) return;
  const lateral = -dx * camera.dirY + dy * camera.dirX;
  const centerX = WIDTH / 2 + lateral * PROJECTION / depth;
  const size = 0.55 * PROJECTION / depth;
  const left = centerX - size / 2;
  const top = HEIGHT / 2 - size / 2;
  const start = Math.max(0, Math.ceil(left));
  const end = Math.min(WIDTH, Math.ceil(left + size));
  for (let x = start; x < end; x++) {
    const sourceX = Math.max(0, Math.min(63, Math.floor((x - left) / size * 64)));
    drawSpriteColumn(s, x, depth, top, top + size, sourceX);
  }
}

function renderScene(s) {
  ctx.fillStyle = "#141923";
  ctx.fillRect(0, 0, WIDTH, HEIGHT / 2);
  ctx.fillStyle = "#292b32";
  ctx.fillRect(0, HEIGHT / 2, WIDTH, HEIGHT / 2);

  const dirX = Math.cos(s.player.angle);
  const dirY = Math.sin(s.player.angle);
  const camera = {
    dirX, dirY,
    planeX: -dirY * PLANE_LENGTH,
    planeY: dirX * PLANE_LENGTH
  };

  for (let x = 0; x < WIDTH; x++) {
    s.archOccluders[x].length = 0;
    const result = castRay(s, camera, 2 * (x + 0.5) / WIDTH - 1);
    s.zBuffer[x] = result.wall.distance;
    drawWallColumn(s, x, result.wall);
    for (let i = result.arches.length - 1; i >= 0; i--) {
      drawWallColumn(s, x, result.arches[i], true);
    }
  }
  drawExitBeacon(s, camera);
}

function drawMinimap(s) {
  const scale = 6, originX = 14, originY = 14;
  ctx.fillStyle = "#080d16dc";
  ctx.fillRect(originX - 5, originY - 5, 118, 118);
  const colors = ["#1c2931", "#955943", "#527f93", "#76628a", "#e0b66b", "", "#6fffb4"];
  for (let y = 0; y < s.map.length; y++) {
    for (let x = 0; x < s.map[y].length; x++) {
      const tile = s.map[y][x];
      const door = tile === 4 ? s.doors.get(`${x},${y}`) : null;
      ctx.fillStyle = door?.open ? "#3c6c59"
        : door?.secret && !s.secretFound ? colors[1] : colors[tile];
      ctx.fillRect(originX + x * scale, originY + y * scale, scale, scale);
    }
  }
  const px = originX + s.player.x * scale;
  const py = originY + s.player.y * scale;
  ctx.save();
  ctx.translate(px, py);
  ctx.rotate(s.player.angle);
  ctx.strokeStyle = "#fff4d6";
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(10, 0);
  ctx.lineTo(6, -3);
  ctx.moveTo(10, 0);
  ctx.lineTo(6, 3);
  ctx.stroke();
  ctx.fillStyle = "#fff4d6";
  ctx.beginPath();
  ctx.arc(0, 0, 2.2, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function formatTime(seconds) {
  const minutes = Math.floor(seconds / 60).toString().padStart(2, "0");
  const remainder = Math.floor(seconds % 60).toString().padStart(2, "0");
  return `${minutes}:${remainder}`;
}

function drawHUD(s) {
  drawMinimap(s);
  ctx.font = "12px monospace";
  ctx.textAlign = "right";
  ctx.fillStyle = "#0a111bd9";
  ctx.fillRect(WIDTH - 117, 9, 108, 44);
  ctx.fillStyle = "#d7e7e7";
  ctx.fillText(`${Math.round(s.fps)} FPS`, WIDTH - 18, 27);
  ctx.fillStyle = "#90b0ba";
  ctx.fillText(formatTime(s.elapsed), WIDTH - 18, 44);

  ctx.textAlign = "center";
  ctx.fillStyle = "#e4e9db99";
  ctx.fillRect(WIDTH / 2 - 3, HEIGHT / 2, 7, 1);
  ctx.fillRect(WIDTH / 2, HEIGHT / 2 - 3, 1, 7);

  if (s.nearbyDoor && !s.complete) {
    ctx.fillStyle = "#080d16dc";
    ctx.fillRect(211, HEIGHT - 76, 218, 30);
    ctx.fillStyle = "#ffe1a6";
    ctx.font = "14px monospace";
    ctx.fillText("Press E to open door", WIDTH / 2, HEIGHT - 56);
  }

  ctx.fillStyle = "#080d16cc";
  ctx.fillRect(0, HEIGHT - 30, WIDTH, 30);
  ctx.font = "11px monospace";
  ctx.fillStyle = "#b7c8d0";
  const locked = document.pointerLockElement === canvas;
  ctx.fillText(
    locked
      ? "WASD move  ·  Mouse / ← → turn  ·  E open  ·  Find the green exit"
      : "Click to capture mouse  ·  WASD move  ·  ← → turn  ·  E open",
    WIDTH / 2, HEIGHT - 11
  );
  if (s.secretFound) {
    ctx.textAlign = "left";
    ctx.fillStyle = "#d7bbff";
    ctx.fillText("SECRET REVEALED", 14, 139);
  }
}

const controlKeys = new Set([
  "KeyW", "KeyA", "KeyS", "KeyD", "KeyE", "ArrowLeft", "ArrowRight"
]);

window.addEventListener("keydown", event => {
  if (!controlKeys.has(event.code)) return;
  event.preventDefault();
  state.keys.add(event.code);
  if (event.code === "KeyE" && !event.repeat) state.interact = true;
});
window.addEventListener("keyup", event => state.keys.delete(event.code));
window.addEventListener("blur", () => {
  state.keys.clear();
  state.mouseDelta = 0;
  state.interact = false;
});
document.addEventListener("pointerlockchange", () => {
  state.keys.clear();
  state.mouseDelta = 0;
});
document.addEventListener("mousemove", event => {
  if (document.pointerLockElement === canvas && !state.complete) {
    state.mouseDelta += event.movementX;
  }
});
canvas.addEventListener("click", () => {
  if (state.complete) return;
  if (state.startedAt === null) state.startedAt = performance.now();
  try {
    const request = canvas.requestPointerLock();
    if (request?.catch) request.catch(() => {});
  } catch (_) {
    // Arrow-key rotation remains available if pointer lock is unavailable.
  }
});
document.getElementById("restart").addEventListener("click", () => {
  state = createState();
  document.getElementById("complete").classList.remove("show");
});

let previousTime = null;
function gameLoop(now) {
  const frameSeconds = previousTime === null ? 1 / 60 : (now - previousTime) / 1000;
  previousTime = now;
  if (frameSeconds > 0) {
    state.frameTimes.push(frameSeconds);
    if (state.frameTimes.length > 30) state.frameTimes.shift();
    state.fps = state.frameTimes.length /
      state.frameTimes.reduce((total, duration) => total + duration, 0);
  }
  // Clamp simulation after tab switches; completion time uses the real clock.
  handleInput(state, Math.min(frameSeconds, 0.05), now);
  renderScene(state);
  drawHUD(state);
  requestAnimationFrame(gameLoop);
}
requestAnimationFrame(gameLoop);
</script>
